<?php
require_once __DIR__.'/includes/functions.php';require_role(['student']);$pageTitle='Reservations';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$bookId=(int)($_POST['book_id']??0);if($action==='reserve'){$s=db()->prepare('SELECT id FROM books WHERE id=? AND is_active=1');$s->execute([$bookId]);if(!$s->fetch())$error='That book is not available in the catalog.';else{$s=db()->prepare("SELECT id FROM reservations WHERE user_id=? AND book_id=? AND status='pending'");$s->execute([current_user()['id'],$bookId]);if($s->fetch())$error='You already have a pending reservation for this book.';else{$s=db()->prepare("INSERT INTO reservations(user_id,book_id,status) VALUES(?,?,'pending')");$s->execute([current_user()['id'],$bookId]);flash('success','Reservation request submitted. A librarian will review it.');redirect('/reservations.php');}}}elseif($action==='cancel'){$s=db()->prepare("UPDATE reservations SET status='cancelled' WHERE id=? AND user_id=? AND status='pending'");$s->execute([(int)($_POST['reservation_id']??0),current_user()['id']]);flash('success','Reservation cancelled.');redirect('/reservations.php');}}
if($_SERVER['REQUEST_METHOD']==='GET'&&isset($_GET['book_id'])){$_SESSION['prefill_book']=(int)$_GET['book_id'];}
$s=db()->prepare('SELECT r.*,b.title,b.author FROM reservations r JOIN books b ON b.id=r.book_id WHERE r.user_id=? ORDER BY r.created_at DESC');$s->execute([current_user()['id']]);$rows=$s->fetchAll();$books=db()->query('SELECT id,title,author FROM books WHERE is_active=1 ORDER BY title')->fetchAll();require __DIR__.'/includes/header.php';
?>
<div class="mb-4"><p class="text-primary small text-uppercase fw-bold mb-1">My library</p><h1 class="page-title mb-1">Book reservations</h1><p class="muted mb-0">Request a title and track its status.</p></div><?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif; ?><div class="surface p-3 p-md-4 mb-4"><h2 class="h5 fw-bold mb-3">Request a book</h2><form method="post" class="row g-2 align-items-end"><?=csrf_field()?><input type="hidden" name="action" value="reserve"><div class="col-md-9"><label class="form-label">Book title</label><select class="form-select" name="book_id" required><option value="">Select a book</option><?php foreach($books as $b): ?><option value="<?=(int)$b['id']?>"><?=e($b['title'])?> — <?=e($b['author'])?></option><?php endforeach; ?></select></div><div class="col-md-3"><button class="btn btn-primary w-100" type="submit">Submit request</button></div></form></div><div class="table-wrap"><table class="table"><thead><tr><th>Book</th><th>Requested</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=e($r['title'])?></strong><div class="small muted"><?=e($r['author'])?></div></td><td><?=e($r['created_at'])?></td><td><span class="badge-soft <?=$r['status']==='approved'?'badge-available':($r['status']==='rejected'||$r['status']==='cancelled'?'badge-unavailable':'')?>"><?=e(ucfirst($r['status']))?></span></td><td><?php if($r['status']==='pending'): ?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="cancel"><input type="hidden" name="reservation_id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-outline-danger" type="submit">Cancel</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php if(!$rows): ?><div class="empty-state">You have no reservations yet.</div><?php endif; ?></div>
<?php require __DIR__.'/includes/footer.php'; ?>
